<script setup lang="ts">
import { useProductivityStore, dateKey } from '~/stores/productivity'
const store=useProductivityStore(); const toast=useToast(); const now=ref(new Date()); let tick:any
onMounted(()=>tick=setInterval(()=>now.value=new Date(),1000)); onBeforeUnmount(()=>clearInterval(tick))
const todayLabel=computed(()=>now.value.toLocaleDateString('fa-IR',{weekday:'long',day:'numeric',month:'long'})); const current=computed(()=>store.nowBlock); const next=computed(()=>store.nextBlock)
const tasks=computed(()=>store.tasks.filter(t=>t.scheduledDate===dateKey()).sort((a,b)=>(a.startTime||'99:99').localeCompare(b.startTime||'99:99')))
const overdue=computed(()=>tasks.value.filter(t=>t.status!=='completed' && t.startTime && t.startTime<now.value.toTimeString().slice(0,5)))
const startTask=(t:any)=>{store.startTimer({label:t.title,durationSeconds:t.estimatedMinutes*60,taskId:t.id,mode:'schedule'});navigateTo(`/focus?taskId=${t.id}`)}
const finish=(t:any)=>store.toggleTask(t.id)
</script>
<template><div class="space-y-6">
<header class="flex flex-col md:flex-row md:items-end justify-between gap-3"><div><p class="text-sm text-gray-500">{{ todayLabel }} · {{ now.toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}) }}</p><h1 class="text-3xl font-black mt-1">مسیر امروز</h1><p class="text-gray-500 mt-1">اینجا مرکز اجرای برنامه است؛ نه فقط نمایش آن.</p></div><div class="flex gap-2"><UButton to="/planner" icon="i-lucide-calendar-plus">چیدن برنامه</UButton><UButton to="/tasks" variant="soft" icon="i-lucide-list-plus">افزودن کار</UButton></div></header>
<UAlert v-if="current" color="primary" variant="soft" icon="i-lucide-zap" :title="`الان وقت «${current.title}» است`" :description="`${current.start} تا ${current.end} · پیشنهاد می‌کنم همین حالا اجراش کنی.`"><template #actions><UButton size="sm" @click="current.taskId ? startTask(store.tasks.find(t=>t.id===current.taskId)) : navigateTo('/focus')">شروع تایمر</UButton></template></UAlert>
<UAlert v-else-if="next" color="neutral" variant="soft" icon="i-lucide-clock" :title="`کار بعدی: ${next.title}`" :description="`${next.start} تا ${next.end}`" />
<div class="grid lg:grid-cols-3 gap-4"><UCard class="lg:col-span-2"><template #header><div class="flex justify-between"><b>برنامه اجرایی امروز</b><UBadge variant="soft">{{ tasks.filter(t=>t.status==='completed').length }}/{{ tasks.length }} انجام‌شده</UBadge></div></template>
<div v-if="tasks.length" class="space-y-2"><div v-for="t in tasks" :key="t.id" class="p-3 rounded-2xl border border-gray-200 dark:border-gray-800 flex items-center gap-3" :class="t.status==='completed'?'opacity-60':''"><div class="w-20 text-xs text-gray-500 font-mono">{{ t.startTime||'—' }}<span v-if="t.endTime">–{{t.endTime}}</span></div><UCheckbox :model-value="t.status==='completed'" @update:model-value="finish(t)"/><div class="flex-1"><div class="font-bold" :class="t.status==='completed'?'line-through':''">{{t.title}}</div><div class="text-xs text-gray-500 mt-1">{{t.estimatedMinutes}} دقیقه · {{t.category}}</div></div><UButton v-if="t.status!=='completed'" size="sm" icon="i-lucide-play" @click="startTask(t)">اجرا</UButton><UBadge v-else color="success" variant="soft">تمام شد</UBadge></div></div><p v-else class="text-sm text-gray-500 py-8 text-center">برای امروز برنامه‌ای نداری. از برنامه‌ریز یک سناریوی روز بساز.</p></UCard>
<UCard><template #header><b>عقب‌افتاده‌ها</b></template><div v-if="overdue.length" class="space-y-2"><div v-for="t in overdue" :key="t.id" class="p-3 rounded-xl bg-warning-50 dark:bg-warning-950/20"><b class="text-sm">{{t.title}}</b><p class="text-xs text-gray-500 mt-1">قرار بود {{t.startTime}} شروع شود.</p><div class="flex gap-2 mt-2"><UButton size="xs" @click="startTask(t)">الان انجامش بده</UButton><UButton size="xs" variant="soft" @click="store.deferTask(t.id)">فردا</UButton></div></div></div><p v-else class="text-sm text-gray-500">عقب‌افتادگی مهمی نداری 👌</p></UCard></div>
<div class="grid md:grid-cols-3 gap-4"><UCard><p class="text-sm text-gray-500">تمرکز امروز</p><b class="text-2xl">{{store.todayFocusMinutes}} دقیقه</b></UCard><UCard><p class="text-sm text-gray-500">هدف امروز</p><b class="text-2xl">{{Math.min(100,Math.round(store.todayFocusMinutes/store.settings.dailyStudyGoalMinutes*100))}}٪</b></UCard><UCard><p class="text-sm text-gray-500">جلسه فعال</p><b class="text-2xl">{{store.activeTimer?'بله':'خیر'}}</b></UCard></div>
</div></template>
